1	/**
2	 * @fileoverview Adapter management REST API routes
3	 *
4	 * This module provides Express routes for managing external adapter plugins:
5	 * - Listing all registered adapters (built-in + external)
6	 * - Installing external adapters from npm packages or local paths
7	 * - Unregistering external adapters
8	 *
9	 * Read-only routes require board org access. Mutating adapter management
10	 * routes require instance-admin access because they can install, reload, or
11	 * toggle server-side adapter code for the whole Paperclip instance.
12	 *
13	 * @module server/routes/adapters
14	 */
15	
16	import { execFile } from "node:child_process";
17	import fs from "node:fs";
18	import { readFile } from "node:fs/promises";
19	import path from "node:path";
20	import { promisify } from "node:util";
21	import { Router } from "express";
22	import {
23	  listServerAdapters,
24	  findServerAdapter,
25	  findActiveServerAdapter,
26	  listEnabledServerAdapters,
27	  registerServerAdapter,
28	  resolveExternalAdapterRegistration,
29	  unregisterServerAdapter,
30	  isOverridePaused,
31	  setOverridePaused,
32	} from "../adapters/registry.js";
33	import {
34	  listAdapterPlugins,
35	  addAdapterPlugin,
36	  removeAdapterPlugin,
37	  getAdapterPluginByType,
38	  getAdapterPluginsDir,
39	  getDisabledAdapterTypes,
40	  setAdapterDisabled,
41	} from "../services/adapter-plugin-store.js";
42	import type { AdapterPluginRecord } from "../services/adapter-plugin-store.js";
43	import type { ServerAdapterModule, AdapterConfigSchema } from "../adapters/types.js";
44	import { loadExternalAdapterPackage, getUiParserSource, getOrExtractUiParserSource, reloadExternalAdapter } from "../adapters/plugin-loader.js";
45	import { logger } from "../middleware/logger.js";
46	import { assertBoardOrgAccess, assertInstanceAdmin } from "./authz.js";
47	import { BUILTIN_ADAPTER_TYPES } from "../adapters/builtin-adapter-types.js";
48	import { expressHandler } from "../http/express-adapter.js";
49	import type { Handler } from "../http/types.js";
50	import type { StorageService } from "../storage/types.js";
51	
52	const execFileAsync = promisify(execFile);
53	
54	// ---------------------------------------------------------------------------
55	// Request / Response types
56	// ---------------------------------------------------------------------------
57	
58	interface AdapterInstallRequest {
59	  /** npm package name (e.g., "droid-paperclip-adapter") or local path */
60	  packageName: string;
61	  /** True if packageName is a local filesystem path */
62	  isLocalPath?: boolean;
63	  /** Target version for npm packages (optional, defaults to latest) */
64	  version?: string;
65	}
66	
67	interface AdapterCapabilities {
68	  supportsInstructionsBundle: boolean;
69	  supportsSkills: boolean;
70	  supportsLocalAgentJwt: boolean;
71	  requiresMaterializedRuntimeSkills: boolean;
72	}
73	
74	interface AdapterInfo {
75	  type: string;
76	  label: string;
77	  source: "builtin" | "external";
78	  modelsCount: number;
79	  loaded: boolean;
80	  disabled: boolean;
81	  capabilities: AdapterCapabilities;
82	  /** True when an external plugin has replaced a built-in adapter of the same type. */
83	  overriddenBuiltin?: boolean;
84	  /** True when the external override for a builtin type is currently paused. */
85	  overridePaused?: boolean;
86	  version?: string;
87	  packageName?: string;
88	  isLocalPath?: boolean;
89	}
90	
91	// ---------------------------------------------------------------------------
92	// Helpers
93	// ---------------------------------------------------------------------------
94	
95	/**
96	 * Resolve the adapter package directory (same rules as plugin-loader).
97	 */
98	function resolveAdapterPackageDir(record: AdapterPluginRecord): string {
99	  return record.localPath
100	    ? path.resolve(record.localPath)
101	    : path.resolve(getAdapterPluginsDir(), "node_modules", record.packageName);
102	}
103	
104	/**
105	 * Read `version` from the adapter's package.json on disk.
106	 * This is the source of truth for what is actually installed (npm or local path).
107	 *
108	 * TODO(cloudflare): readAdapterPackageVersionFromDisk uses fs.readFileSync to
109	 * read package.json from a locally installed npm package directory. The entire
110	 * concept of locally installed adapter packages assumes a persistent filesystem
111	 * and a Node-compatible module loader. For Workers compatibility the installed
112	 * version should be persisted to the database at install time and read from
113	 * there instead of from disk at request time.
114	 */
115	function readAdapterPackageVersionFromDisk(record: AdapterPluginRecord): string | undefined {
116	  try {
117	    const pkgDir = resolveAdapterPackageDir(record);
118	    const raw = fs.readFileSync(path.join(pkgDir, "package.json"), "utf-8");
119	    const v = JSON.parse(raw).version;
120	    return typeof v === "string" && v.trim().length > 0 ? v.trim() : undefined;
121	  } catch {
122	    return undefined;
123	  }
124	}
125	
126	function buildAdapterCapabilities(adapter: ServerAdapterModule): AdapterCapabilities {
127	  return {
128	    supportsInstructionsBundle: adapter.supportsInstructionsBundle ?? false,
129	    supportsSkills: Boolean(adapter.listSkills || adapter.syncSkills),
130	    supportsLocalAgentJwt: adapter.supportsLocalAgentJwt ?? false,
131	    requiresMaterializedRuntimeSkills: adapter.requiresMaterializedRuntimeSkills ?? false,
132	  };
133	}
134	
135	function buildAdapterInfo(adapter: ServerAdapterModule, externalRecord: AdapterPluginRecord | undefined, disabledSet: Set<string>): AdapterInfo {
136	  const fromDisk = externalRecord ? readAdapterPackageVersionFromDisk(externalRecord) : undefined;
137	  return {
138	    type: adapter.type,
139	    label: adapter.type, // ServerAdapterModule doesn't have a separate "label" field; type serves as label
140	    source: externalRecord ? "external" : "builtin",
141	    modelsCount: (adapter.models ?? []).length,
142	    loaded: true, // If it's in the registry, it's loaded
143	    disabled: disabledSet.has(adapter.type),
144	    capabilities: buildAdapterCapabilities(adapter),
145	    overriddenBuiltin: externalRecord ? BUILTIN_ADAPTER_TYPES.has(adapter.type) : undefined,
146	    overridePaused: BUILTIN_ADAPTER_TYPES.has(adapter.type) ? isOverridePaused(adapter.type) : undefined,
147	    // Prefer on-disk package.json so the UI reflects bumps without relying on store-only fields.
148	    version: fromDisk ?? externalRecord?.version,
149	    packageName: externalRecord?.packageName,
150	    isLocalPath: externalRecord?.localPath ? true : undefined,
151	  };
152	}
153	
154	/**
155	 * Normalize a local path that may be a Windows path into a WSL-compatible path.
156	 *
157	 * - Windows paths (e.g., "C:\\Users\\...") are converted via `wslpath -u`.
158	 * - Paths already starting with `/mnt/` or `/` are returned as-is.
159	 */
160	async function normalizeLocalPath(rawPath: string): Promise<string> {
161	  // Already a POSIX path (WSL or native Linux)
162	  if (rawPath.startsWith("/")) {
163	    return rawPath;
164	  }
165	
166	  // Windows path detection: C:\ or C:/ pattern
167	  if (/^[A-Za-z]:[\\/]/.test(rawPath)) {
168	    try {
169	      const { stdout } = await execFileAsync("wslpath", ["-u", rawPath]);
170	      return stdout.trim();
171	    } catch (err) {
172	      logger.warn({ err, rawPath }, "wslpath conversion failed; using path as-is");
173	      return rawPath;
174	    }
175	  }
176	
177	  return rawPath;
178	}
179	
180	/**
181	 * Register an external adapter module into the server registry via the
182	 * hot-install path, resolving `sessionManagement` identically to how the
183	 * init-time IIFE does. Module-provided `sessionManagement` is honored first,
184	 * with fallback to the host registry by type for builtin-type overrides.
185	 *
186	 * Keeps the hot-install and init-time paths at parity so an adapter installed
187	 * via `POST /api/adapters/install` has the same shape in the registry as the
188	 * same adapter loaded on the next server restart.
189	 */
190	function registerWithSessionManagement(adapter: ServerAdapterModule): void {
191	  registerServerAdapter(resolveExternalAdapterRegistration(adapter));
192	}
193	
194	// ---------------------------------------------------------------------------
195	// Router
196	// ---------------------------------------------------------------------------
197	
198	export function adapterRoutes() {
199	  const router = Router();
200	
201	  // Storage is not used by any adapter handler.
202	  const storageSentinel = new Proxy({} as StorageService, {
203	    get(_target, prop) {
204	      throw new Error(`adapter handler unexpectedly accessed storage.${String(prop)}`);
205	    },
206	  });
207	
208	  // A placeholder Db sentinel — adapter routes do not touch the database.
209	  // expressHandler requires a Db in deps; supply a proxy that throws on access.
210	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
211	  const dbSentinel = new Proxy({} as any, {
212	    get(_target, prop) {
213	      throw new Error(`adapter handler unexpectedly accessed db.${String(prop)}`);
214	    },
215	  });
216	
217	  const adapterDeps = { db: dbSentinel, storage: storageSentinel };
218	
219	  // ---------------------------------------------------------------------------
220	  // Authz helpers — assertBoardOrgAccess and assertInstanceAdmin from authz.ts
221	  // accept RequestCtx directly (both satisfy the AuthzReq structural interface).
222	  // ---------------------------------------------------------------------------
223	
224	  // config schema cache shared across the router's lifetime
225	  const configSchemaCache = new Map<string, {
226	    adapter: ServerAdapterModule;
227	    schema: AdapterConfigSchema;
228	    fetchedAt: number;
229	  }>();
230	  const CONFIG_SCHEMA_TTL_MS = 30_000;
231	
232	  /**
233	   * GET /api/adapters
234	   *
235	   * List all registered adapters (built-in + external).
236	   * Each entry includes whether the adapter is built-in or external,
237	   * its model count, and load status.
238	   */
239	  const listAdapters: Handler = async (ctx) => {
240	    assertBoardOrgAccess(ctx);
241	
242	    const registeredAdapters = listServerAdapters();
243	    const externalRecords = new Map(
244	      listAdapterPlugins().map((r) => [r.type, r]),
245	    );
246	    const disabledSet = new Set(getDisabledAdapterTypes());
247	
248	    const result: AdapterInfo[] = registeredAdapters.map((adapter) =>
249	      buildAdapterInfo(adapter, externalRecords.get(adapter.type), disabledSet),
250	    ).sort((a, b) => a.type.localeCompare(b.type));
251	
252	    return Response.json(result);
253	  };
254	
255	  /**
256	   * POST /api/adapters/install
257	   *
258	   * Install an external adapter from an npm package or local path.
259	   *
260	   * Request body:
261	   * - packageName: string (required) — npm package name or local path
262	   * - isLocalPath?: boolean (default false)
263	   * - version?: string — target version for npm packages
264	   */
265	  const installAdapter: Handler = async (ctx) => {
266	    assertInstanceAdmin(ctx);
267	    const body = await ctx.json<AdapterInstallRequest>();
268	    const { packageName, isLocalPath = false, version } = body;
269	
270	    if (!packageName || typeof packageName !== "string") {
271	      return Response.json({ error: "packageName is required and must be a string." }, { status: 400 });
272	    }
273	
274	    // Strip version suffix if the UI sends "pkg@1.2.3" instead of separating it
275	    let canonicalName = packageName;
276	    let explicitVersion = version;
277	    const versionSuffix = packageName.match(/@(\d+\.\d+\.\d+.*)$/);
278	    if (versionSuffix) {
279	      const lastAtIndex = packageName.lastIndexOf("@");
280	      if (lastAtIndex > 0 && !explicitVersion) {
281	        canonicalName = packageName.slice(0, lastAtIndex);
282	        explicitVersion = versionSuffix[1];
283	      }
284	    }
285	
286	    try {
287	      let installedVersion: string | undefined;
288	      let moduleLocalPath: string | undefined;
289	
290	      if (!isLocalPath) {
291	        const pluginsDir = getAdapterPluginsDir();
292	        const spec = explicitVersion ? `${canonicalName}@${explicitVersion}` : canonicalName;
293	
294	        logger.info({ spec, pluginsDir }, "Installing adapter package via npm");
295	
296	        await execFileAsync("npm", ["install", "--no-save", spec], {
297	          cwd: pluginsDir,
298	          timeout: 120_000,
299	        });
300	
301	        // TODO(cloudflare): reading package.json from the npm install directory
302	        // uses node:fs/promises at request time. For Workers compatibility the
303	        // installed version should be persisted to the DB by the install job and
304	        // read from there rather than from the local filesystem.
305	        try {
306	          const pkgJsonPath = path.join(pluginsDir, "node_modules", canonicalName, "package.json");
307	          const pkgContent = await import("node:fs/promises");
308	          const pkgRaw = await pkgContent.readFile(pkgJsonPath, "utf-8");
309	          const pkg = JSON.parse(pkgRaw);
310	          const v = pkg.version;
311	          installedVersion =
312	            typeof v === "string" && v.trim().length > 0 ? v.trim() : explicitVersion;
313	        } catch {
314	          installedVersion = explicitVersion;
315	        }
316	      } else {
317	        moduleLocalPath = path.resolve(await normalizeLocalPath(packageName));
318	        // TODO(cloudflare): reading package.json from a local-path adapter
319	        // directory uses node:fs/promises at request time. For Workers
320	        // compatibility the version should be captured during the install step
321	        // and stored in the database rather than read from disk at request time.
322	        try {
323	          const pkgRaw = await readFile(path.join(moduleLocalPath, "package.json"), "utf-8");
324	          const v = JSON.parse(pkgRaw).version;
325	          if (typeof v === "string" && v.trim().length > 0) {
326	            installedVersion = v.trim();
327	          }
328	        } catch {
329	          // leave installedVersion undefined if package.json is missing
330	        }
331	      }
332	
333	      const adapterModule = await loadExternalAdapterPackage(canonicalName, moduleLocalPath);
334	
335	      if (BUILTIN_ADAPTER_TYPES.has(adapterModule.type)) {
336	        return Response.json({
337	          error: `Adapter type "${adapterModule.type}" is a built-in adapter and cannot be overwritten.`,
338	        }, { status: 409 });
339	      }
340	
341	      const existing = findServerAdapter(adapterModule.type);
342	      const isReinstall = existing !== null;
343	      if (existing) {
344	        unregisterServerAdapter(adapterModule.type);
345	        logger.info({ type: adapterModule.type }, "Unregistered existing adapter for replacement");
346	      }
347	
348	      registerWithSessionManagement(adapterModule);
349	
350	      const record: AdapterPluginRecord = {
351	        packageName: canonicalName,
352	        localPath: moduleLocalPath,
353	        version: installedVersion ?? explicitVersion,
354	        type: adapterModule.type,
355	        installedAt: new Date().toISOString(),
356	      };
357	      addAdapterPlugin(record);
358	
359	      logger.info(
360	        { type: adapterModule.type, packageName: canonicalName },
361	        "External adapter installed and registered",
362	      );
363	
364	      return Response.json({
365	        type: adapterModule.type,
366	        packageName: canonicalName,
367	        version: installedVersion ?? explicitVersion,
368	        installedAt: record.installedAt,
369	        requiresRestart: isReinstall,
370	      }, { status: 201 });
371	    } catch (err) {
372	      const message = err instanceof Error ? err.message : String(err);
373	      logger.error({ err, packageName }, "Failed to install external adapter");
374	
375	      if (message.includes("npm") || message.includes("ERR!")) {
376	        return Response.json({ error: `npm install failed: ${message}` }, { status: 500 });
377	      }
378	      return Response.json({ error: `Failed to install adapter: ${message}` }, { status: 500 });
379	    }
380	  };
381	
382	  /**
383	   * PATCH /api/adapters/:type
384	   *
385	   * Enable or disable an adapter.
386	   *
387	   * Request body: { "disabled": boolean }
388	   */
389	  const patchAdapter: Handler = async (ctx) => {
390	    assertInstanceAdmin(ctx);
391	    const adapterType = ctx.param("type");
392	    if (!adapterType) return Response.json({ error: "Adapter type is required." }, { status: 400 });
393	    const body = await ctx.json<{ disabled?: boolean }>();
394	    const { disabled } = body;
395	
396	    if (typeof disabled !== "boolean") {
397	      return Response.json({ error: "Request body must include { \"disabled\": true|false }." }, { status: 400 });
398	    }
399	
400	    const existing = findServerAdapter(adapterType);
401	    if (!existing) {
402	      return Response.json({ error: `Adapter "${adapterType}" is not registered.` }, { status: 404 });
403	    }
404	
405	    const changed = setAdapterDisabled(adapterType, disabled);
406	
407	    if (changed) {
408	      logger.info({ type: adapterType, disabled }, "Adapter enabled/disabled");
409	    }
410	
411	    return Response.json({ type: adapterType, disabled, changed });
412	  };
413	
414	  /**
415	   * PATCH /api/adapters/:type/override
416	   *
417	   * Pause or resume an external adapter's override of a builtin type.
418	   */
419	  const patchAdapterOverride: Handler = async (ctx) => {
420	    assertInstanceAdmin(ctx);
421	    const adapterType = ctx.param("type");
422	    if (!adapterType) return Response.json({ error: "Adapter type is required." }, { status: 400 });
423	    const body = await ctx.json<{ paused?: boolean }>();
424	    const { paused } = body;
425	
426	    if (typeof paused !== "boolean") {
427	      return Response.json({ error: "\"paused\" (boolean) is required in request body." }, { status: 400 });
428	    }
429	
430	    if (!BUILTIN_ADAPTER_TYPES.has(adapterType)) {
431	      return Response.json({ error: `Type "${adapterType}" is not a builtin adapter.` }, { status: 400 });
432	    }
433	
434	    const changed = setOverridePaused(adapterType, paused);
435	
436	    logger.info({ type: adapterType, paused, changed }, "Adapter override toggle");
437	
438	    return Response.json({ type: adapterType, paused, changed });
439	  };
440	
441	  /**
442	   * DELETE /api/adapters/:type
443	   *
444	   * Unregister an external adapter. Built-in adapters cannot be removed.
445	   */
446	  const deleteAdapter: Handler = async (ctx) => {
447	    assertInstanceAdmin(ctx);
448	    const adapterType = ctx.param("type");
449	
450	    if (!adapterType) {
451	      return Response.json({ error: "Adapter type is required." }, { status: 400 });
452	    }
453	
454	    if (BUILTIN_ADAPTER_TYPES.has(adapterType)) {
455	      return Response.json({
456	        error: `Cannot remove built-in adapter "${adapterType}".`,
457	      }, { status: 403 });
458	    }
459	
460	    const existing = findServerAdapter(adapterType);
461	    if (!existing) {
462	      return Response.json({
463	        error: `Adapter "${adapterType}" is not registered.`,
464	      }, { status: 404 });
465	    }
466	
467	    const externalRecord = getAdapterPluginByType(adapterType);
468	    if (!externalRecord) {
469	      return Response.json({
470	        error: `Adapter "${adapterType}" is not an externally installed adapter.`,
471	      }, { status: 404 });
472	    }
473	
474	    if (externalRecord.packageName && !externalRecord.localPath) {
475	      try {
476	        const pluginsDir = getAdapterPluginsDir();
477	        await execFileAsync("npm", ["uninstall", externalRecord.packageName], {
478	          cwd: pluginsDir,
479	          timeout: 60_000,
480	        });
481	        logger.info(
482	          { type: adapterType, packageName: externalRecord.packageName },
483	          "npm uninstall completed for external adapter",
484	        );
485	      } catch (err) {
486	        logger.warn(
487	          { err, type: adapterType, packageName: externalRecord.packageName },
488	          "npm uninstall failed for external adapter; continuing with unregister",
489	        );
490	      }
491	    }
492	
493	    unregisterServerAdapter(adapterType);
494	    removeAdapterPlugin(adapterType);
495	
496	    logger.info({ type: adapterType }, "External adapter unregistered and removed");
497	
498	    return Response.json({ type: adapterType, removed: true });
499	  };
500	
501	  /**
502	   * POST /api/adapters/:type/reload
503	   *
504	   * Reload an external adapter at runtime.
505	   */
506	  const reloadAdapter: Handler = async (ctx) => {
507	    assertInstanceAdmin(ctx);
508	    const type = ctx.param("type");
509	    if (!type) return Response.json({ error: "Adapter type is required." }, { status: 400 });
510	
511	    if (BUILTIN_ADAPTER_TYPES.has(type) && !getAdapterPluginByType(type)) {
512	      return Response.json({ error: "Cannot reload built-in adapter." }, { status: 400 });
513	    }
514	
515	    try {
516	      const newModule = await reloadExternalAdapter(type);
517	
518	      if (!newModule) {
519	        return Response.json({ error: `Adapter "${type}" is not an externally installed adapter.` }, { status: 404 });
520	      }
521	
522	      unregisterServerAdapter(type);
523	      registerWithSessionManagement(newModule);
524	      configSchemaCache.delete(type);
525	
526	      const record = getAdapterPluginByType(type);
527	      let newVersion: string | undefined;
528	      if (record) {
529	        newVersion = readAdapterPackageVersionFromDisk(record);
530	        if (newVersion) {
531	          addAdapterPlugin({ ...record, version: newVersion });
532	        }
533	      }
534	
535	      logger.info({ type, version: newVersion }, "External adapter reloaded at runtime");
536	
537	      return Response.json({ type, version: newVersion, reloaded: true });
538	    } catch (err) {
539	      const message = err instanceof Error ? err.message : String(err);
540	      logger.error({ err, type }, "Failed to reload external adapter");
541	      return Response.json({ error: `Failed to reload adapter: ${message}` }, { status: 500 });
542	    }
543	  };
544	
545	  /**
546	   * POST /api/adapters/:type/reinstall
547	   *
548	   * Reinstall an npm-sourced external adapter.
549	   */
550	  const reinstallAdapter: Handler = async (ctx) => {
551	    assertInstanceAdmin(ctx);
552	    const type = ctx.param("type");
553	    if (!type) return Response.json({ error: "Adapter type is required." }, { status: 400 });
554	
555	    if (BUILTIN_ADAPTER_TYPES.has(type) && !getAdapterPluginByType(type)) {
556	      return Response.json({ error: "Cannot reinstall built-in adapter." }, { status: 400 });
557	    }
558	
559	    const record = getAdapterPluginByType(type);
560	    if (!record) {
561	      return Response.json({ error: `Adapter "${type}" is not an externally installed adapter.` }, { status: 404 });
562	    }
563	
564	    if (record.localPath) {
565	      return Response.json({ error: "Local-path adapters cannot be reinstalled. Use Reload instead." }, { status: 400 });
566	    }
567	
568	    try {
569	      const pluginsDir = getAdapterPluginsDir();
570	
571	      logger.info({ type, packageName: record.packageName }, "Reinstalling adapter package via npm");
572	
573	      await execFileAsync("npm", ["install", "--no-save", record.packageName], {
574	        cwd: pluginsDir,
575	        timeout: 120_000,
576	      });
577	
578	      const newModule = await reloadExternalAdapter(type);
579	      if (!newModule) {
580	        return Response.json({ error: "npm install succeeded but adapter reload failed." }, { status: 500 });
581	      }
582	
583	      unregisterServerAdapter(type);
584	      registerWithSessionManagement(newModule);
585	      configSchemaCache.delete(type);
586	
587	      let newVersion: string | undefined;
588	      const updatedRecord = getAdapterPluginByType(type);
589	      if (updatedRecord) {
590	        newVersion = readAdapterPackageVersionFromDisk(updatedRecord);
591	        if (newVersion) {
592	          addAdapterPlugin({ ...updatedRecord, version: newVersion });
593	        }
594	      }
595	
596	      logger.info({ type, version: newVersion }, "Adapter reinstalled from npm");
597	
598	      return Response.json({ type, version: newVersion, reinstalled: true });
599	    } catch (err) {
600	      const message = err instanceof Error ? err.message : String(err);
601	      logger.error({ err, type }, "Failed to reinstall adapter");
602	      return Response.json({ error: `Reinstall failed: ${message}` }, { status: 500 });
603	    }
604	  };
605	
606	  /**
607	   * GET /api/adapters/:type/config-schema
608	   *
609	   * Serve a declarative config schema for an adapter's UI form fields.
610	   */
611	  const getAdapterConfigSchema: Handler = async (ctx) => {
612	    assertBoardOrgAccess(ctx);
613	    const type = ctx.param("type");
614	    if (!type) return Response.json({ error: "Adapter type is required." }, { status: 400 });
615	
616	    const adapter = findActiveServerAdapter(type);
617	    if (!adapter) {
618	      return Response.json({ error: `Adapter "${type}" is not registered.` }, { status: 404 });
619	    }
620	    if (!adapter.getConfigSchema) {
621	      return Response.json({ error: `Adapter "${type}" does not provide a config schema.` }, { status: 404 });
622	    }
623	
624	    const cached = configSchemaCache.get(type);
625	    if (cached && cached.adapter === adapter && Date.now() - cached.fetchedAt < CONFIG_SCHEMA_TTL_MS) {
626	      return Response.json(cached.schema);
627	    }
628	
629	    try {
630	      const schema = await adapter.getConfigSchema();
